AND NOT EXISTS(SELECT 1 FROM post_growth_record g WHERE g.post_id=CASE WHEN review.target_type=1 THEN review.target_id ELSE (SELECT gc.target_id FROM comment gc WHERE review.target_type=4 AND gc.id=review.target_id AND gc.target_type=1) END) AND review.review_state IS NULL AND (versioned.task_id IS NULL OR versioned.resource_namespace=target.resource_namespace) AND target.resource_namespace IS NOT NULL AND target.resource_namespace != 'ARTICLE'
AND target.resource_namespace IN #{space}
AND 1 = 0

AND EXISTS(SELECT 1 FROM post_growth_record g WHERE g.post_id=CASE WHEN review.target_type=1 THEN review.target_id ELSE (SELECT gc.target_id FROM comment gc WHERE review.target_type=4 AND gc.id=review.target_id AND gc.target_type=1) END AND g.record_type=#{growthType}AND g.organization_id=#{growthOrganizationId} AND g.organization_id IN #{org}) AND (versioned.task_id IS NULL OR versioned.resource_namespace=target.resource_namespace) AND target.resource_namespace IS NOT NULL AND target.resource_namespace != 'ARTICLE'
AND target.resource_namespace IN #{space}
AND 1 = 0

